import pandas as pd
import numpy as np
import json

ref_file = r"C:\Users\sandeeppawar\Downloads\aida-eval\data\file_generation_en\reference\FG_200\visitor_count_statistics_res.xlsx"
pred_file = r"C:\Users\sandeeppawar\Downloads\aida-eval\runs\aida-ctrl\work\FG_200\visitor_count_statistics.xlsx"

ref_df = pd.read_excel(ref_file)
pred_df_raw = pd.read_excel(pred_file, header=None)
pred_df = pd.read_excel(pred_file, header=2)

def to_py(val):
    if pd.isna(val):
        return None
    if isinstance(val, (np.integer, np.int64)):
        return int(val)
    if isinstance(val, (np.floating, np.float64)):
        return float(val)
    return str(val)

comparison = {
    'reference': {
        'shape': list(ref_df.shape),
        'columns': [str(c) for c in ref_df.columns],
        'rows': [[to_py(v) for v in row] for _, row in ref_df.iterrows()]
    },
    'predicted_raw': {
        'total_row': [to_py(v) for v in pred_df_raw.iloc[0]],
        'empty_row': [to_py(v) for v in pred_df_raw.iloc[1]],
        'header_row': [to_py(v) for v in pred_df_raw.iloc[2]]
    },
    'predicted': {
        'shape': list(pred_df.shape),
        'columns': [str(c) for c in pred_df.columns],
        'rows': [[to_py(v) for v in row] for _, row in pred_df.iterrows()]
    }
}

print(json.dumps(comparison, indent=2), flush=True)
